// Partage : pose ou retire le label du technicien sur un memo de Laurent ClimatPro.
// Ranger (bloc A trancher) : memo a trier ou pro-ou-perso -> Laurent ClimatPro (p=1) ou Perso (p=0). Rien d'autre n'est modifiable.
const v = $('Verifier partage').first().json;
const t = $input.first().json || {};
const lab = Array.isArray(t.labels) ? t.labels.slice() : [];
const memo = String(t.id || '') === v.id && !t.checked && (lab.includes('memo') || lab.includes('commande'));
if (v.qui === 'ranger') {
  const ok = memo && (lab.includes('a-trier') || lab.includes('pro-ou-perso') || t.project_id === '6hh3xGRJ424mj3J6');
  const labels = lab.filter(l => !['a-trier', 'pro-ou-perso'].includes(l));
  const content = String(t.content || '').replace(/^(À trier|A trier) : /, '');
  const dest = v.partage ? { section_id: lab.includes('devis') ? '6hh4248WJ2ppj3M8' : '6hh4246PVq2H9Fp8' } : { project_id: '6hh423vGr88f287j' };
  return [{ json: { ok, id: v.id, labels, maj: { labels, content }, dest, deplacer: true } }];
}
const ok = memo && t.project_id === '6hh423vJrW7RvQQg';
const labels = v.partage ? [...new Set(lab.concat([v.qui]))] : lab.filter(l => l !== v.qui);
return [{ json: { ok, id: v.id, labels, maj: { labels }, partage: v.partage, deplacer: false } }];

// Section « Véhicules » (Quartix) : vue admin uniquement (Laurent). Les techniciens ne voient ni le menu ni la position des véhicules.
// Données : quartix_etat (position en direct, workflow « Quartix - Positions ») + quartix_jours (journal par jour, workflow « Quartix - Historique »).
// Par défaut (pas de ?vj) : vue EN DIRECT = où sont les camions maintenant + journal du jour (même vide, ex. le week-end).
// Historique : paramètre ?vj=AAAA-MM-JJ (flèches, calendrier ; liens GET : la page est en bac à sable, pas de fetch). Jour demandé sans trajet -> jour précédent avec trajets.
// Bureau : lien « Véhicules » sous « Clients » -> section #vehicules après la section Clients. Mobile : section dans l'onglet Planning.
let html = $('Liens Fait').first().json.html || '';
const acc = $('Verifier acces').first().json || {};
if (acc.role !== 'admin') return [{ json: { html } }];
const all = n => { try { return $(n).all().map(i => i.json || {}); } catch (e) { return []; } };
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const now = DateTime.now().setZone('Europe/Paris');
const today = now.toISODate();
const dt = iso => DateTime.fromISO(iso).setZone('Europe/Paris');
const hm = iso => iso ? dt(iso).toFormat("HH'h'mm") : '';
const jourLong = iso => DateTime.fromISO(iso, { zone: 'Europe/Paris' }).setLocale('fr').toFormat('cccc d LLLL');
const quand = iso => !iso ? '' : (dt(iso).toISODate() === today ? hm(iso) : jourLong(dt(iso).toISODate()) + ', ' + hm(iso));
const duree = m => m == null ? '' : (m >= 60 ? Math.floor(m / 60) + 'h' + String(m % 60).padStart(2, '0') : m + ' min');
const kmTxt = k => String(Math.round((k || 0) * 10) / 10).replace('.', ',') + ' km';
const lieuCourt = s => String(s || '').replace(/,?\s*\d{5}\s*/, ', ').replace(/,\s*$/, '').replace(/\s+,/g, ',');
const PERS_ID = { 5066: 'Laurent', 5069: 'Christophe', 9965: 'Axel', 5198: 'Axel' };
const COUL = { 'EA 940 EC': '#1f6fa8', 'FL 192 RP': '#4b5a5f' };
const PROPRIO = { 'EA 940 EC': ' (Laurent)' };
// ---------- Données ----------
let etat = null;
try { etat = JSON.parse((all('Lire Quartix (table)')[0] || {}).etat_json || 'null'); } catch (e) { etat = null; }
const J = ($('Jour vehicules').first().json) || { vj: today, demande: false };
const parse = r => { try { return JSON.parse(r.journal_json); } catch (e) { return null; } };
const valide = r => r && /^\d{4}-\d{2}-\d{2}$/.test(String(r.jour || ''));
let lignesJour = all('Lire journee (table)').filter(valide).filter(r => r.jour === J.vj);
const precedents = all('Jour precedent (table)').filter(valide);
const suivants = all('Jour suivant (table)').filter(valide);
let jourAff = J.vj, repli = false;
if (!lignesJour.length && precedents.length && J.demande) { jourAff = precedents[0].jour; lignesJour = precedents.filter(r => r.jour === jourAff); repli = true; }
const journaux = {};
for (const r of lignesJour) { const j = parse(r); if (j && j.immat) journaux[j.immat] = j; }
const estAujourdhui = jourAff === today;
const vehLive = (etat && Array.isArray(etat.vehicules)) ? etat.vehicules : [];
if (!vehLive.length && !Object.keys(journaux).length) return [{ json: { html } }];
// ---------- Liens de navigation (on garde les autres paramètres de la page) ----------
let q = {}; try { q = $('GET /tableau').first().json.query || {}; } catch (e) { q = {}; }
const lien = jour => { const p = Object.assign({}, q); delete p.vj; if (jour && jour !== today) p.vj = jour; const s = Object.keys(p).filter(k => p[k] !== '' && p[k] != null).map(k => encodeURIComponent(k) + '=' + encodeURIComponent(p[k])).join('&'); return '?' + s + '#vehicules'; };
const veille = DateTime.fromISO(jourAff, { zone: 'Europe/Paris' }).minus({ days: 1 }).toISODate();
const suivant = (suivants.find(r => r.jour > jourAff) || {}).jour || null;
const nav = '<div class="vh-jours">'
  + '<a class="vh-fleche" href="' + esc(lien(veille)) + '" aria-label="Jour précédent">‹</a>'
  + '<strong class="vh-date">' + (estAujourdhui ? '<span class="vh-direct">En direct</span>' : '') + esc(jourLong(jourAff)) + '</strong>'
  + (suivant ? '<a class="vh-fleche" href="' + esc(lien(suivant)) + '" aria-label="Jour suivant">›</a>' : '<span class="vh-fleche vh-off">›</span>')
  + (!estAujourdhui ? '<a class="vh-ajd" href="' + esc(lien(today)) + '">Retour au direct</a>' : '')
  + '<label class="vh-cal-l">Aller au <input type="date" class="vh-cal" value="' + esc(jourAff) + '" min="' + esc(DateTime.fromISO(today, { zone: 'Europe/Paris' }).minus({ days: 365 }).toISODate()) + '" max="' + esc(today) + '" data-modele="' + esc(lien('2000-01-01')) + '" data-ajd="' + esc(lien(today)) + '" data-today="' + esc(today) + '"></label>'
  + '</div>' + (repli && J.demande ? '<p class="petit muted vh-note">Pas de trajet le ' + esc(jourLong(J.vj)) + ' : affichage du ' + esc(jourLong(jourAff)) + '.</p>' : '');
// ---------- Journal d'un véhicule ----------
const DEPOT = [43.5788, 6.95012];
const dist = (a, c) => { const R = 6371000, t = Math.PI / 180; const dLa = (c[0] - a[0]) * t, dLo = (c[1] - a[1]) * t; const x = Math.sin(dLa / 2) ** 2 + Math.cos(a[0] * t) * Math.cos(c[0] * t) * Math.sin(dLo / 2) ** 2; return 2 * R * Math.asin(Math.sqrt(x)); };
const nomLieu = (lieu, lat, lon) => (/^climatpro$/i.test(String(lieu || '').trim()) || (typeof lat === 'number' && dist([lat, lon], DEPOT) < 200)) ? 'Dépôt' : lieuCourt(lieu);
function journalHtml(j, immat) {
  const stops = [];
  if (!j || !Array.isArray(j.trajets) || !j.trajets.length) return { html: '<p class="petit muted">Aucun trajet ce jour-là.</p>', stops };
  const T = j.trajets, A = j.arrets || [];
  const L = [];
  const t0 = T[0];
  L.push('<li class="vh-l vh-l-dep"><span class="vh-h"><b class="vh-b vh-b-dep">D</b>' + hm(t0.dep) + '</span><span class="vh-t">Départ · ' + esc(nomLieu(t0.de, t0.deLat, t0.deLon)) + '</span></li>');
  if (typeof t0.deLat === 'number') stops.push({ lat: t0.deLat, lon: t0.deLon, t: 'dep', n: 'D', p: '<strong>Départ ' + hm(t0.dep) + '</strong><br>' + esc(nomLieu(t0.de, t0.deLat, t0.deLon)) });
  let surClient = 0, autre = 0, num = 0;
  T.forEach((t, k) => {
    const a = A.find(x => x.arrivee === t.arr);
    L.push('<li class="vh-l vh-l-traj"><span class="vh-h"></span><span class="vh-t">trajet ' + duree(t.min) + ' · ' + kmTxt(t.km) + (a ? '' : ' → ' + esc(nomLieu(t.a, t.aLat, t.aLon)) + ' <span class="muted">(passage)</span>') + '</span></li>');
    if (!a) return;
    const i = stops.length;
    num++;
    const fin = !a.depart;
    let lib, cls = 'vh-l-' + a.type;
    if (a.type === 'client' && a.client) {
      const c = a.client;
      const qui = [...new Set((c.techniciens || []).map(x => PERS_ID[x]).filter(Boolean))].join(', ');
      lib = '<strong>' + esc(c.nom || c.objet || 'Rendez-vous') + '</strong>' + (c.objet && c.nom ? ' · ' + esc(c.objet) : '') + (qui ? ' · ' + esc(qui) : '') + '<br><span class="vh-lieu">' + esc(lieuCourt(a.lieu)) + '</span>';
      if (a.minutes) surClient += a.minutes;
    } else if (a.type === 'fournisseur') {
      lib = '<strong>' + esc(a.lieuNom || 'Fournisseur') + '</strong> · fournisseur<br><span class="vh-lieu">' + esc(lieuCourt(a.lieu)) + '</span>';
    } else if (a.type === 'depot') { lib = 'Dépôt'; }
    else if (a.type === 'maison') { lib = 'Maison' + (immat === 'EA 940 EC' ? '' : ' de Laurent'); }
    else { lib = '<span class="muted">hors intervention</span><br><span class="vh-lieu">' + esc(lieuCourt(a.lieu)) + '</span>'; if (a.minutes) autre += a.minutes; }
    const heures = hm(a.arrivee) + (a.depart ? ' → ' + hm(a.depart) : '');
    L.push('<li class="vh-l vh-arret ' + cls + '" data-v="' + esc(immat) + '" data-i="' + i + '" tabindex="0"><span class="vh-h"><b class="vh-b vh-b-' + a.type + '">' + num + '</b>' + heures + '</span><span class="vh-t">' + (fin ? '<span class="muted">Arrivée · </span>' : '') + lib + '</span><span class="vh-d">' + (fin ? '' : duree(a.minutes)) + '</span></li>');
    if (typeof a.lat === 'number') stops.push({ lat: a.lat, lon: a.lon, t: a.type, n: String(num), p: '<strong>' + num + '. ' + heures + (a.minutes ? ' · ' + duree(a.minutes) : '') + '</strong><br>' + lib });
  });
  const tot = '<p class="vh-tot"><span>Chez les clients <strong>' + duree(surClient) + '</strong></span><span>Conduite <strong>' + duree(j.conduiteMin) + '</strong></span><span><strong>' + kmTxt(j.km) + '</strong></span>' + (autre ? '<span class="muted">Hors intervention ' + duree(autre) + '</span>' : '') + '</p>';
  return { html: tot + '<ol class="vh-journal">' + L.join('') + '</ol>', stops };
}
// ---------- Fiches + données carte ----------
const immats = [...new Set(vehLive.map(v => v.immat).concat(Object.keys(journaux)))];
const ordre = ['FL 192 RP', 'EA 940 EC'];
immats.sort((a, b) => (ordre.indexOf(a) + 1 || 9) - (ordre.indexOf(b) + 1 || 9));
const V = [];
const fiches = [], panneaux = [], onglets = [];
for (const im of immats) {
  const v = vehLive.find(x => x.immat === im) || {};
  const j = journaux[im];
  const nom = (v.nom || (j && j.nom) || im) + (PROPRIO[im] || '');
  const coul = COUL[im] || '#1f6fa8';
  const jh = journalHtml(j, im);
  let statut = '', statutTxt = '';
  const live24 = !!(etat && etat.jour === today);
  if (v.immat) {
    const depuis = v.dernierSignal ? ' depuis ' + quand(v.dernierSignal) : '';
    let lib, suite;
    if (v.enRoute && live24) { lib = 'En route'; suite = v.vitesse ? ' · ' + v.vitesse + ' km/h' : ''; }
    else if (v.depot) { lib = 'Au dépôt'; suite = depuis; }
    else if (/(Imp\.?|Chem\.?|Impasse|Chemin) du Moulin/i.test(v.adresse || '')) { lib = 'À la maison'; suite = depuis; }
    else { lib = 'À l’arrêt'; suite = depuis; }
    statutTxt = lib + suite;
    statut = '<p class="vh-statut"><strong>' + esc(lib) + '</strong>' + esc(suite) + '</p>' + (v.adresse && !(v.enRoute && live24) ? '<p class="petit muted">' + esc(v.adresse) + '</p>' : '');
  }
  const ech = [['Révision', v.echeances && v.echeances.revision], ['Assurance', v.echeances && v.echeances.assurance], ['Contrôle technique', v.echeances && v.echeances.ct]]
    .filter(([, d]) => d).map(([n, d]) => { const k = Math.round(DateTime.fromISO(d).diff(now, 'days').days); return k <= 30 ? '<p class="vh-alerte">' + n + (k < 0 ? ' dépassée depuis ' + (-k) + ' j' : ' dans ' + k + ' j') + '</p>' : ''; }).join('');
  fiches.push('<div class="vh" data-v="' + esc(im) + '" tabindex="0" role="button" aria-label="Voir ' + esc(nom) + ' sur la carte"><div class="vh-tete"><span class="vh-nom"><i class="vh-pastille" style="background:' + coul + '"></i>' + esc(nom) + '</span><span class="petit muted">' + esc(im) + '</span></div>' + statut + ech + '</div>');
  onglets.push('<button type="button" class="vh-onglet" data-v="' + esc(im) + '"><i class="vh-pastille" style="background:' + coul + '"></i>' + esc(nom) + '</button>');
  const dernier = (estAujourdhui && !j && precedents.length) ? precedents[0].jour : null;
  const vide = estAujourdhui && !j ? '<p class="petit muted">Aucun trajet aujourd’hui pour l’instant.' + (dernier ? ' <a href="' + esc(lien(dernier)) + '">Voir le dernier jour roulé (' + esc(jourLong(dernier)) + ')</a>' : '') + '</p>' : jh.html;
  panneaux.push('<div class="vh-panneau" data-v="' + esc(im) + '" hidden>' + vide + '</div>');
  const trace = j && Array.isArray(j.trajets) ? j.trajets.map(t => t.trace || []).filter(t => t.length > 1) : [];
  const live = (estAujourdhui && typeof v.lat === 'number') ? { lat: v.lat, lon: v.lon, p: '<strong>' + esc(nom) + '</strong>' + (statutTxt ? '<br>' + esc(statutTxt) : '') + (v.adresse ? '<br>' + esc(v.adresse) : '') } : null;
  V.push({ im, n: nom, c: coul, trace, stops: jh.stops, live, route: !!(v.enRoute && live24) });
}
const majDt = etat && etat.maj ? dt(etat.maj) : null;
const ageMaj = majDt ? Math.round(now.diff(majDt, 'minutes').minutes) : 9999;
const fraicheur = majDt ? (ageMaj > 15 ? 'position de ' + quand(etat.maj) : 'position à jour ' + hm(etat.maj)) : '';
const STYLE = '<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" integrity="sha256-p4NxAoJBhIIN+hmNHrzRCf9tD/miZyoHS5obTRR9BMY=" crossorigin="">'
  + '<style id="style-vehicules">'
  + '#vehicules{scroll-margin-top:16px}'
  + '.vehicules .vh-jours{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:0 0 10px}'
