  + '.vehicules .vh-fleche:hover{background:#0000000d}.vehicules .vh-off{opacity:.3}'
  + '.vehicules .vh-cal-l{margin-left:auto;font-size:13px;display:inline-flex;align-items:center;gap:6px}.vehicules .vh-cal{font:inherit;font-size:13px;padding:5px 8px;border-radius:10px;border:1px solid var(--couleur-bordure,#e3e8ea);background:transparent;color:inherit}'
  + '.vehicules .vh-b{display:inline-flex;align-items:center;justify-content:center;min-width:20px;height:20px;padding:0 4px;margin-right:6px;border-radius:999px;font:700 11px/1 system-ui,sans-serif;color:#fff;background:#7a8589;vertical-align:1px}'
