  + 'var choisir=function(im,zoom){q("[data-v]").forEach(function(x){var on=x.getAttribute("data-v")===im;if(x.classList.contains("vh-panneau"))x.hidden=!on;if(x.classList.contains("vh-onglet"))x.setAttribute("aria-pressed",on?"true":"false");if(x.classList.contains("vh"))x.classList.toggle("vh-sel",on);});if(window.__vhSel)window.__vhSel(im,zoom);};'
  + 'var init=V.filter(function(v){return v.route;})[0]||V.filter(function(v){return v.stops.length||v.trace.length;})[0]||V[0];'
