// Encadre « Devis signés à planifier » (table devis_a_planifier, remplie toutes les 30 min par le workflow
// « Climapro - Devis signes a planifier »). Une ligne disparaît d'elle-même dès qu'une intervention est créée
// (n° de devis dans l'intervention, ou intervention chez le même client après la signature).
// Laurent (admin) voit tout ; Christophe voit les siens (entretiens, dépannages) ; les autres ne voient rien.
// Rouge au-delà de 7 jours après la signature. Aucun montant affiché.
try {
const RETARD_JOURS = 7;
let html = (($('Fil equipe').first() || {}).json || {}).html || '';
const acc = (() => { try { return $('Verifier acces').first().json || {}; } catch (e) { return {}; } })();
if (!acc.ok || !html) return [{ json: { html } }];
const norm = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
const qui = norm(acc.nom);
const toutVoir = !!acc.admin && !acc.apercu;
const rows = $input.all().map(i => i.json || {}).filter(r => r.reference && r.planifie !== true);
const miens = rows.filter(r => toutVoir || norm(r.responsable) === qui);
if (!toutVoir && !miens.length && qui !== 'christophe') return [{ json: { html } }];
const now = DateTime.now().setZone('Europe/Paris');
const esc = x => String(x == null ? '' : x).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const tel = t => { let d = String(t || '').replace(/[^\d+]/g, ''); if (/^33\d{9}$/.test(d)) d = '+' + d; return d.length >= 10 ? d : ''; };
const lignes = miens.map(r => {
  const s = DateTime.fromISO(String(r.signe_le || ''), { zone: 'utc' }).setZone('Europe/Paris');
  const j = s.isValid ? Math.floor(now.startOf('day').diff(s.startOf('day'), 'days').days) : 0;
  return { r, j, s };
}).sort((a, b) => b.j - a.j);
const nbRetard = lignes.filter(x => x.j > RETARD_JOURS).length;
const STYLE = '<style>'
  + '.dp{margin:0 0 18px;padding:16px;background:var(--couleur-surface,#fff);border:1px solid var(--couleur-bordure,#e3e8ea);border-radius:18px}'
