  + '.dp-item--retard .dp-age{color:#b3261e}'
  + '.dp-qui{display:inline-block;margin-left:6px;padding:1px 8px;border-radius:999px;font-size:11px;font-weight:700;background:#eef2f4;color:#41555b;vertical-align:middle}'
