  html = html.slice(0, e + 10) + bloc(' data-onglet="planning"') + html.slice(e + 10);
}
html = html.replace('</head>', STYLE + '</head>');
return [{ json: { html } }];

} catch (e) {
  // En cas de souci, la page s'affiche sans l'encadre plutot que de planter
  return [{ json: { html: (($('Fil equipe').first() || {}).json || {}).html || '' } }];
}

// Meme regle que l'outil Memos du bot : technicien = projet Equipe + memos de Laurent ClimatPro partages avec lui (label a son prenom). Jamais Perso, Holding, Idees.
// Admin (Laurent) : tout memo affiche sur sa page, y compris le bloc A trancher (Boite de reception, Perso pro-ou-perso).
const v = $('Verifier demande').first().json;
const t = $input.first().json || {};
const P = { climatpro: '6hh423vJrW7RvQQg', equipe: '6hh423vw4vGgHFPw' };
const n = s => String(s || '').trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const moi = n(v.nom);
const lab = t.labels || [];
const estMemo = lab.includes('memo') || lab.includes('commande');
const autorise = String(t.id || '') === v.id && estMemo && !t.checked && (v.role === 'admin' || t.project_id === P.equipe || (t.project_id === P.climatpro && !!moi && lab.includes(moi)));
return [{ json: { autorise, id: v.id, token: v.token } }];

