/* Livraison 02 : contraste mobile, action Telegram et décor séparé du texte. */
.mobile-entete .logo small{color:var(--couleur-sous-titre-mobile)}
.mobile-accueil{background-image:linear-gradient(#f8f6eeeb,#f8f6eeeb),url('../images/hero-mobile.jpg')}
.navigation-mobile button{display:flex;align-items:center;justify-content:center;flex-direction:column;gap:4px;min-height:48px;min-width:44px;padding:0;border:0;background:transparent;font:inherit;font-size:10px;color:#4e646b;cursor:pointer}
.navigation-mobile a[aria-current="page"]{box-shadow:inset 0 -3px var(--couleur-accent);border-radius:3px}
.progression-rdv{margin-top:12px}
.rdv--journee{border-left-color:#83aaa4}
.exemple-rdv{max-width:360px;margin-top:18px}
@media(max-width:700px){
  .application .hero{display:flex;flex-direction:column;align-items:stretch;gap:20px;min-height:0;background:var(--couleur-surface);padding:25px 22px 0}
  .application .hero-texte{max-width:none}
  .application .hero::after{content:"";display:block;flex-shrink:0;height:var(--hauteur-decor-etroit);margin:0 -22px;background:url('../images/hero-bureau.jpg') right center/cover no-repeat}
}

/* Livraison 04 : socle agrandi, débordement discret. Aucun changement de structure HTML.
   Le flux réserve le débordement supérieur et latéral, ombre comprise. */
:root {
  --socle-fond:linear-gradient(145deg,#eeefed,#f6f5f2);
  --objet-ombre:drop-shadow(0 5px 3px #173b4929);
}
.memo-entete {
  padding-top:14px;
  padding-left:4px;
  gap:18px;
  overflow:visible;
}
.illustration {
  position:relative;
  isolation:isolate;
  width:88px;
  height:88px;
  padding:0;
  border-radius:18px;
  background:var(--socle-fond);
  overflow:visible;
}
.illustration img {
  position:absolute;
  z-index:1;
  width:96px;
  height:96px;
  max-width:none;
  left:-4px;
  top:-12px;
  object-fit:contain;
  filter:var(--objet-ombre);
  pointer-events:none;
}
/* Le pseudo-élément crée le socle derrière l'image déjà présente. */
.prochain-heure {
  display:grid;
  grid-template-columns:minmax(0,1fr) 96px;
  column-gap:16px;
  align-items:center;
  isolation:isolate;
  overflow:visible;
  padding-top:14px;
}
.prochain-heure > div {grid-column:1;grid-row:1;min-width:0;overflow-wrap:anywhere}
.prochain-heure::before {
  content:"";
  grid-column:2;
  grid-row:1;
  justify-self:center;
  align-self:end;
  width:88px;
  height:88px;
  border-radius:18px;
  background:var(--socle-fond);
  pointer-events:none;
}
.prochain-heure img {
  grid-column:2;
  grid-row:1;
  position:relative;
  z-index:1;
  width:96px;
