  }
} catch (e) {}
for (const nom of Object.keys(table)) {
  if (!nom.startsWith('icones/') && table[nom] !== IMG + nom) html = html.split(IMG + nom).join(table[nom]);
}

// ---- Avatars en initiales -> image si elle existe (ex. avatar-axel.png) ----
for (const [prenom, init] of [['Axel', 'AX']]) {
  const url = table['avatar-' + prenom.toLowerCase() + '.png'];
  if (!url) continue;
  const re = new RegExp('<span class="avatar avatar--initiales ([^"]*)" role="img" aria-label="' + prenom + '">' + init + '<\\/span>', 'g');
  html = html.replace(re, '<img class="avatar $1" src="' + url + '" alt="' + prenom + '" width="38" height="38">');
}

// ---- Icônes d'objet sur les cartes mémo ----
try {
  const objets = {};
  for (const src of ['Lire memos', 'Lire commandes']) {
    let items = [];
