    for (const it of items) {
      const j = it.json || {};
      const liste = Array.isArray(j.results) ? j.results : (j.id ? [j] : []);
      for (const t of liste) {
        const m = String(t.description || '').match(/Ic[oô]ne : ([a-z0-9-]+)/i);
        if (m) objets[String(t.id)] = m[1].toLowerCase();
      }
