  html = html.replace(/<article class="carte-memo[\s\S]*?<\/article>/g, art => {
    const id = (art.match(/name="id" value="([^"]+)"/) || [])[1];
    const mot = id && objets[id];
    const url = mot && table['icones/' + mot + '.png'];
    if (!url) return art;
    return art.replace(/(<div class="illustration"><img src=")[^"]*(")/, '$1' + url + '$2');
  });
} catch (e) {}

// ---- Correctif : choix du jour sur mobile ----
html = html.replace("var p=g.parentNode;q('[data-jour]',p)", "var p=g.parentNode;if(!q('[data-jour]',p).some(function(d){return d.tagName!=='BUTTON';}))p=document;q('[data-jour]',p)");

