html = html.replace('</body>', SCRIPT_LOGO + '</body>');
if (table['icone-app.png']) html = html.replace('</head>', '<link rel="apple-touch-icon" sizes="180x180" href="' + table['icone-app.png'] + '"><link rel="icon" type="image/png" href="' + table['icone-app.png'] + '"></head>');

// ---- Météo par jour ----
let j = {}; try { j = $('Lire meteo semaine').first().json || {}; } catch (e) {}
const I = p => '<svg class="icone" viewBox="0 0 24 24" aria-hidden="true"><path d="' + p + '"/></svg>';
const NUAGE = 'M7 18h10a4 4 0 0 0 0-8 6 6 0 0 0-11.3 1.5A3.5 3.5 0 0 0 7 18';
const ICOM = { soleil: I('M12 3v2M12 19v2M3 12h2M19 12h2M5.6 5.6l1.4 1.4M17 17l1.4 1.4M5.6 18.4 7 17M17 7l1.4-1.4M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8'), nuages: I(NUAGE), brouillard: I(NUAGE + 'M5 21h14'),
  pluie: I(NUAGE + 'M9 20l-1 2M13 20l-1 2M17 20l-1 2'), neige: I(NUAGE + 'M8 21h.1M12 21h.1M16 21h.1'), orage: I(NUAGE + 'M13 14l-2 4h3l-2 4') };
const etatDe = c => c >= 95 ? 'orage' : (c >= 71 && c <= 77) || c === 85 || c === 86 ? 'neige' : (c >= 51 && c <= 67) || (c >= 80 && c <= 82) ? 'pluie' : c === 45 || c === 48 ? 'brouillard' : c >= 2 ? 'nuages' : 'soleil';
const LIB = { soleil: 'Beau temps', nuages: 'Nuageux', brouillard: 'Brouillard', pluie: 'Pluie', neige: 'Neige', orage: 'Orage' };
