if (j.daily && j.daily.time) {
  const D = j.daily, H = j.hourly || { time: [], precipitation: [] };
  const hh = i => +String(H.time[i]).slice(11, 13);
  D.time.forEach((k, n) => {
    // Heures de travail (7 h - 19 h) de ce jour
    const idx = H.time.map((t, i) => i).filter(i => String(H.time[i]).slice(0, 10) === k && hh(i) >= 7 && hh(i) <= 19);
    const pluie = idx.filter(i => (H.precipitation[i] || 0) >= 0.2).map(hh);
    let etat = etatDe(D.weather_code[n] || 0);
