try {
  let cur = {};
  try { cur = ($('Lire meteo').first().json || {}).current || {}; } catch (e) {}
  let etatJour = (html.match(/class="hero meteo-([a-z]+)"/) || [])[1] || '';
  if (!etatJour) etatJour = etatDe(Number(cur.weather_code || 0));
  const nuit = cur.is_day === 0;
  const AMB = { soleil: 'soleil', nuages: 'nuages', brouillard: 'nuages', pluie: 'pluie', orage: 'pluie', neige: 'pluie' };
  const amb = nuit ? 'nuit' : (AMB[etatJour] || 'soleil');
  let change = false;
  for (const f of ['bureau', 'mobile']) {
    const v = table['hero-' + f + '-' + amb + '.jpg'];
    if (!v) continue;
    for (const ancien of [table['hero-' + f + '.jpg'], IMG + 'hero-' + f + '.jpg']) {
