if (!(acc.admin && !acc.apercu && acc.role === 'admin')) return [{ json: { html } }];
// --- SHA-256 / HMAC-SHA256 en JavaScript pur (aucune dépendance au module crypto de n8n) ---
const utf8 = s => { const o = []; for (const ch of String(s)) { const c = ch.codePointAt(0); if (c < 128) o.push(c); else if (c < 2048) o.push(192 | c >> 6, 128 | c & 63); else if (c < 65536) o.push(224 | c >> 12, 128 | c >> 6 & 63, 128 | c & 63); else o.push(240 | c >> 18, 128 | c >> 12 & 63, 128 | c >> 6 & 63, 128 | c & 63); } return o; };
const hex = b => b.map(x => (x < 16 ? '0' : '') + x.toString(16)).join('');
function sha256(m) {
  const K = [], H = []; let p = 2;
  for (let c = 0; c < 64; p++) { let pr = true; for (let d = 2; d * d <= p; d++) if (p % d === 0) { pr = false; break; } if (pr) { if (c < 8) H[c] = (Math.pow(p, 1 / 2) * 4294967296) | 0; K[c++] = (Math.pow(p, 1 / 3) * 4294967296) | 0; } }
  const l = m.length * 8, b = m.slice(); b.push(0x80); while (b.length % 64 !== 56) b.push(0);
  for (let i = 7; i >= 0; i--) b.push(i > 3 ? 0 : (l >>> (i * 8)) & 255);
  const r = (x, n) => (x >>> n) | (x << (32 - n));
  for (let o = 0; o < b.length; o += 64) {
    const w = [];
    for (let i = 0; i < 64; i++) {
      if (i < 16) w[i] = (b[o + 4 * i] << 24) | (b[o + 4 * i + 1] << 16) | (b[o + 4 * i + 2] << 8) | b[o + 4 * i + 3];
      else { const a = w[i - 15], c = w[i - 2]; w[i] = (w[i - 16] + (r(a, 7) ^ r(a, 18) ^ (a >>> 3)) + w[i - 7] + (r(c, 17) ^ r(c, 19) ^ (c >>> 10))) | 0; }
    }
    let [A, B, C, D, E, F, G, I] = H;
    for (let i = 0; i < 64; i++) {
      const t1 = (I + (r(E, 6) ^ r(E, 11) ^ r(E, 25)) + ((E & F) ^ (~E & G)) + K[i] + w[i]) | 0;
      const t2 = ((r(A, 2) ^ r(A, 13) ^ r(A, 22)) + ((A & B) ^ (A & C) ^ (B & C))) | 0;
      I = G; G = F; F = E; E = (D + t1) | 0; D = C; C = B; B = A; A = (t1 + t2) | 0;
    }
    [A, B, C, D, E, F, G, I].forEach((v, i) => { H[i] = (H[i] + v) | 0; });
  }
  const out = []; H.forEach(v => { for (let i = 3; i >= 0; i--) out.push((v >>> (i * 8)) & 255); }); return out;
}
