const egal = (a, b) => { a = String(a); b = String(b); if (a.length !== b.length) return false; let d = 0; for (let i = 0; i < a.length; i++) d |= a.charCodeAt(i) ^ b.charCodeAt(i); return d === 0; };
const signer = (secret, tid, exp) => hex(hmac(utf8(secret), utf8('v1.' + tid + '.' + exp)));
// --- fin des outils ---
// Lien signe (GET) : la page n8n est servie en sandbox (origine null), un fetch POST n'emporte pas le cookie.
// La signature lie le lien a la session de Laurent, au memo et a l'action : un lien forge ailleurs est refuse.
const secret = String((($('Lire secrets').first() || {}).json || {}).cookie_secret || '').trim();
const tid = (String(((($('GET /tableau').first() || {}).json || {}).headers || {}).cookie || '').match(/(?:^|;\s*)cp_session=(\d{1,20})\./) || [])[1] || '';
if (secret.length < 32 || !tid) return [{ json: { html } }];
const signe = (id, qui, p) => hex(hmac(utf8(secret), utf8('partage.v1.' + tid + '.' + id + '.' + qui + '.' + p)));
const lire = nm => { try { const j = $(nm).first().json || {}; return j.results || j.items || []; } catch (e) { return []; } };
const T = {};
lire('Lire memos').concat(lire('Lire commandes')).forEach(t => { if (t && t.id) T[String(t.id)] = t; });
const CP = '6hh423vJrW7RvQQg';
