TECHS.forEach(x => { const m = html.match(new RegExp('<img class="avatar[^"]*" src="([^"]+)" alt="' + x.nom + '"')); if (m) x.av = '<img class="avatar" src="' + m[1] + '" alt="" width="38" height="38">'; });
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const texte = (nom, on) => on ? nom + ' voit ce mémo. Toucher pour le lui retirer.' : nom + ' ne voit pas ce mémo. Toucher pour le lui partager.';
const rangee = t => '<div class="memo-partage"><small>Visible par</small>' + TECHS.map(x => {
