  + '.confies summary span{display:inline-block;min-width:22px;margin-left:6px;padding:1px 7px;border-radius:999px;background:var(--fond-succes,#e5f3e8);font-size:12px;text-align:center}.confies .grille-memos{margin-top:10px}</style>';
html = html.replace('</head>', STYLE + '</head>');
return [{ json: { html } }];

// Sous-catégories des mémos (colonne « parent » de la table memos_categories).
// Une rubrique dont le parent est renseigné devient une sous-catégorie : sur la page, un seul bouton pour le groupe
// (ex. « Interventions à planifier »), puis une rangée de sous-filtres (Toutes, Entretien, Dépannage, Installation).
// Placé après « Categories et a trancher » (qui classe les mémos) : ce noeud ne fait que regrouper l'affichage.
const base = (($input.first() || {}).json) || {};
let html = base.html || '';
const n = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const cle = s => n(s).replace(/[^a-z0-9-]/g, '');
let rows = [];
try { rows = $('Lire categories').all().map(i => i.json || {}); } catch (e) {}
rows = rows.filter(r => r.cle && (r.actif === true || r.actif === 'true'))
  .map(r => ({ cle: cle(r.cle), lib: String(r.libelle || r.cle), ordre: Number(r.ordre) || 99, parent: cle(r.parent || '') }))
  .sort((a, b) => a.ordre - b.ordre);
const LIB = {}; rows.forEach(r => { LIB[r.cle] = r.lib; });
const PARENT = {}; rows.forEach(r => { if (r.parent && r.parent !== r.cle && LIB[r.parent]) PARENT[r.cle] = r.parent; });
const GROUPES = [...new Set(Object.values(PARENT))];
if (!GROUPES.length || !html) return [{ json: base }];
const ENFANTS = g => rows.filter(r => PARENT[r.cle] === g).map(r => r.cle);

// 1) Cartes : data-categorie = groupe, data-sous = sous-catégorie
html = html.replace(/<article class="carte-memo([^"]*)" data-categorie="([a-z0-9-]+)"/g, (a, cls, c) => {
  const g = PARENT[c];
  return g ? '<article class="carte-memo' + cls + '" data-categorie="' + g + '" data-sous="' + c + '"' : a;
});

// 2) Filtres : les boutons des sous-catégories sont remplacés par un bouton de groupe + une rangée de sous-filtres
html = html.replace(/<div class="filtres"([^>]*)>([\s\S]*?)<\/div>/g, (m, attrs, inner) => {
  const btns = inner.match(/<button[\s\S]*?<\/button>/g) || [];
  const cDe = b => (b.match(/data-filtre="([a-z0-9-]+)"/) || [])[1] || '';
