// Lien GET signe genere par le noeud Partage memos ; session admin + signature obligatoires
const req = $('GET /tableau-partage').first().json;
const q = req.query || {};
const id = String(q.id || '').trim();
const qui = String(q.qui || '').trim().toLowerCase();
const p = String(q.p || '');
const sec = (() => { try { return $('Lire secrets (partage)').first().json || {}; } catch (e) { return {}; } })();
const secret = String(sec.cookie_secret || '').trim();
const rows = $input.all().map(i => i.json).filter(r => r && (r.actif === true || r.actif === 'true'));
const row = session(req.headers, secret, rows);
const forme = /^[A-Za-z0-9]{1,40}$/.test(id) && ['christophe', 'axel', 'ranger'].includes(qui) && ['0', '1'].includes(p) && /^[0-9a-f]{64}$/.test(String(q.s || ''));
const ok = !!row && (row.role || '') === 'admin' && forme && egal(String(q.s), hex(hmac(utf8(secret), utf8('partage.v1.' + String(row.telegram_id).trim() + '.' + id + '.' + qui + '.' + p))));
return [{ json: { ok, id: ok ? id : '', qui: ok ? qui : '', partage: p === '1' } }];
